<template><q-page class="page"><section class="top"><div><p class="eyebrow">ADMINISTRAÇÃO</p><h1>Importar questões</h1><p>Valide conteúdo, fonte e candidatos duplicados antes de criar rascunhos.</p></div></section><q-card flat class="card"><q-card-section class="q-gutter-md"><q-select v-model="format" outlined label="Formato" :options="['JSON','CSV']"/><q-input v-model="content" outlined type="textarea" autogrow label="Conteúdo da importação"/><q-btn unelevated no-caps color="primary" label="Validar importação" :loading="loading" @click="previewImport"/></q-card-section></q-card><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-card v-if="report" flat class="card report"><q-card-section><h2>Relatório de validação</h2><p>{{ report.validRows }} linhas válidas · {{ report.invalidRows }} bloqueadas para revisão</p><q-list bordered separator><q-item v-for="row in report.rows" :key="row.rowNumber"><q-item-section><q-item-label>Linha {{ row.rowNumber }} — {{ row.valid ? 'pronta para rascunho' : 'revisão necessária' }}</q-item-label><q-item-label v-if="row.errors.length" caption :class="row.errors.some(item => item.code === 'DUPLICATE_CANDIDATE') ? 'candidate' : ''">{{ row.errors.map(item => item.message).join(' · ') }}</q-item-label></q-item-section></q-item></q-list><div v-if="report.importId" class="commit"><q-select v-model="examId" outlined label="Concurso" :options="exams" option-label="name" option-value="id" emit-value map-options @update:model-value="loadPositions"/><q-select v-model="positionId" outlined label="Cargo" :disable="!examId" :options="positions" option-label="name" option-value="id" emit-value map-options @update:model-value="loadSyllabi"/><q-select v-model="syllabusId" outlined label="Edital" :disable="!positionId" :options="syllabi" option-label="name" option-value="id" emit-value map-options/><q-btn unelevated no-caps color="primary" label="Confirmar linhas válidas" :disable="!syllabusId || !report.validRows" :loading="loading" @click="commitImport"/></div><q-banner v-if="success" rounded class="success">{{ success }}</q-banner></q-card-section></q-card></q-page></template>
<script setup lang="ts">import { onMounted, ref } from 'vue';import { useImport } from './useImport';const format=ref<'JSON'|'CSV'>('JSON');const content=ref('');const syllabusId=ref('');const examId=ref('');const positionId=ref('');const { commit,error,exams,loadExams,loadPositions: loadCatalogPositions,loadSyllabi: loadCatalogSyllabi,loading,positions,preview,report,success,syllabi }=useImport();async function loadPositions(){positionId.value='';syllabusId.value='';await loadCatalogPositions(examId.value)}async function loadSyllabi(){syllabusId.value='';await loadCatalogSyllabi(positionId.value)}async function previewImport(){await preview(format.value,content.value)}async function commitImport(){await commit(syllabusId.value)}onMounted(loadExams);</script>
<style scoped>.page{max-width:1000px;margin:auto;padding:42px 34px}.top{margin-bottom:20px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.card{background:#fff;border:1px solid #e5ecf6;border-radius:16px;margin-top:16px}.error{margin-top:16px;background:#fff3f2;color:#ae2f25}.success{margin-top:16px;background:#edf9f1;color:#22764a}.commit{display:grid;gap:12px;margin-top:18px}.candidate{color:#a45d00;font-weight:700}@media(max-width:600px){.page{padding:28px 16px}}</style>
